mapper.select:
select 
from result_view_period_settings rv
where rv.setting_id = #{settingId}

select count(*)
from result_view_period_settings rv
where rv.active_yn = 'Y'
  and rv.evaluation_year = #{evaluationYear}
  and rv.college_organization_code = #{collegeOrganizationCode}
  and rv.department_organization_code is not distinct from #{departmentOrganizationCode}
  and rv.visibility_scope = #{visibilityScope}
  and tsrange(rv.view_start_at, rv.view_end_at, '[]') && tsrange(#{viewStartAt}, #{viewEndAt}, '[]')

      and rv.setting_id != #{settingId}

select count(*)
from evaluation_organization_mappings eom
where eom.user_id = #{userId}
  and eom.organization_code = #{organizationCode}
  and eom.business_type = 'FACULTY_ACHIEVEMENT'
  and eom.data_scope in ('DEPARTMENT','COLLEGE','BUSINESS','ALL')

select 
from result_view_period_settings rv
where rv.active_yn = 'Y'
  and (rv.department_organization_code = #{organizationCode}
       or (rv.department_organization_code is null and rv.college_organization_code = #{organizationCode}))
  and rv.visibility_scope = #{visibilityScope}
  and rv.view_start_at <= #{requestAt}
  and rv.view_end_at >= #{requestAt}
order by rv.view_start_at desc
limit 1
